#include "../wall8.cpu"

#bankdef cart {
    #addr 0xA000
    #size 0x5000
    #outp 0x0000
}

#bank cart
#addr 0xA000

; ============================================================================
; WALL-8 - RICK ANIMADO 320x240 1-BIT / DELTA VIDEO
;
; GIF original:
;   54 frames
;   40 ms/frame
;   2,16 segundos
;
; Cartucho:
;   320x240 real, 1 bit/pixel
;   5 frames representativos: 0, 11, 22, 33, 44
;   ~431 ms entre frames
;
; FRAME 0:
;   framebuffer inteiro comprimido por RLE.
;
; FRAMES 1..4:
;   apenas bytes que mudaram em relacao ao frame anterior.
;
; Para economizar ROM mantendo o detalhamento Bayer, o fundo do frame 0 fica
; congelado fora da regiao X=88..247. A regiao central onde ocorre o movimento
; continua animada.
; ============================================================================

VIDEO_DATA       = $F200
VIDEO_CMD        = $F201
VIDEO_X          = $F202
VIDEO_Y          = $F203
VIDEO_STATUS     = $F204
SYSTEM_STATUS    = $F300

VIDEO_BUSY_MASK  = $01
TIMER_1MS_MASK   = $01
VIDEO_MODE_320   = $12

RUN_COUNT        = $0200
CUR_X            = $0201
CUR_Y            = $0202

START:

    CALL VIDEO_WAIT
    STI VIDEO_CMD, #VIDEO_MODE_320
    CALL VIDEO_WAIT

ANIMATION_LOOP:

    PTR KEYFRAME_DATA
    CALL DRAW_KEYFRAME
    CALL WAIT_FRAME_TIME

    PTR DELTA_1
    CALL APPLY_DELTA
    CALL WAIT_FRAME_TIME

    PTR DELTA_2
    CALL APPLY_DELTA
    CALL WAIT_FRAME_TIME

    PTR DELTA_3
    CALL APPLY_DELTA
    CALL WAIT_FRAME_TIME

    PTR DELTA_4
    CALL APPLY_DELTA
    CALL WAIT_FRAME_TIME

    JMP ANIMATION_LOOP


; ============================================================================
; KEYFRAME RLE
;
; $00       fim
; $01-$7F   literal N bytes
; $80-$FE   repetir um byte N vezes, N=(cmd&$7F)+1
; ============================================================================

DRAW_KEYFRAME:

    CALL VIDEO_WAIT
    STI VIDEO_X, #$00
    STI VIDEO_Y, #$00

KEY_CMD:

    LDA [PTR+]
    CMP A, #$00
    JZ KEY_DONE

    TEST A, #$80
    JNZ KEY_REPEAT

    STA RUN_COUNT

KEY_LITERAL_LOOP:

    LDA [PTR+]
    MOV B, A

    CALL VIDEO_WAIT

    MOV A, B
    STA VIDEO_DATA

    LDA RUN_COUNT
    DEC A
    STA RUN_COUNT
    JNZ KEY_LITERAL_LOOP

    JMP KEY_CMD


KEY_REPEAT:

    AND A, #$7F
    INC A
    STA RUN_COUNT

    LDB [PTR+]

KEY_REPEAT_LOOP:

    CALL VIDEO_WAIT

    MOV A, B
    STA VIDEO_DATA

    LDA RUN_COUNT
    DEC A
    STA RUN_COUNT
    JNZ KEY_REPEAT_LOOP

    JMP KEY_CMD


KEY_DONE:

    CALL VIDEO_WAIT
    RET


; ============================================================================
; DELTA
;
; $00       fim do frame
; $01-$7F   pular N bytes da VRAM
; $81-$FF   escrever N=(cmd&$7F) bytes literais
; ============================================================================

APPLY_DELTA:

    STI CUR_X, #$00
    STI CUR_Y, #$00

    CALL VIDEO_WAIT
    STI VIDEO_X, #$00
    STI VIDEO_Y, #$00

DELTA_CMD:

    LDA [PTR+]
    CMP A, #$00
    JZ DELTA_DONE

    TEST A, #$80
    JNZ DELTA_LITERAL

    STA RUN_COUNT

DELTA_SKIP_LOOP:

    CALL ADVANCE_CURSOR

    LDA RUN_COUNT
    DEC A
    STA RUN_COUNT
    JNZ DELTA_SKIP_LOOP

    JMP DELTA_CMD


DELTA_LITERAL:

    AND A, #$7F
    STA RUN_COUNT

    CALL VIDEO_WAIT

    LDA CUR_X
    STA VIDEO_X

    LDA CUR_Y
    STA VIDEO_Y


DELTA_LITERAL_LOOP:

    LDA [PTR+]
    MOV B, A

    CALL VIDEO_WAIT

    MOV A, B
    STA VIDEO_DATA

    CALL ADVANCE_CURSOR

    LDA RUN_COUNT
    DEC A
    STA RUN_COUNT
    JNZ DELTA_LITERAL_LOOP

    JMP DELTA_CMD


DELTA_DONE:

    CALL VIDEO_WAIT
    RET


; ============================================================================
; CURSOR LINEAR: 40 bytes por linha.
; ============================================================================

ADVANCE_CURSOR:

    LDA CUR_X
    INC A
    CMP A, #$28
    JNZ CURSOR_STORE_X

    STI CUR_X, #$00

    LDA CUR_Y
    INC A
    STA CUR_Y
    RET


CURSOR_STORE_X:

    STA CUR_X
    RET


VIDEO_WAIT:

    LDA VIDEO_STATUS
    TEST A, #VIDEO_BUSY_MASK
    JNZ VIDEO_WAIT
    RET


; ============================================================================
; ~431 ms entre frames.
;
; TIMER_1MS = 1024 Hz.
; 147 ticks = 143,55 ms.
; 3 x 147 = 430,66 ms.
; ============================================================================

WAIT_FRAME_TIME:

    CALL WAIT_147MS
    CALL WAIT_147MS
    CALL WAIT_147MS
    RET


WAIT_147MS:

    LDB #$93

WAIT_147MS_LOOP:

    CALL WAIT_1MS
    DEC B
    JNZ WAIT_147MS_LOOP
    RET


WAIT_1MS:

    STI SYSTEM_STATUS, #$00

WAIT_1MS_LOOP:

    LDA SYSTEM_STATUS
    TEST A, #TIMER_1MS_MASK
    JZ WAIT_1MS_LOOP
    RET


